style.css:
@-moz-document domain("roblox.com"), domain("web.roblox.com") {
/* Cache les noms dans les profils */
    .profile-name,
    .header-title,
    .profile-header-name,
    .text-name,
    .name-container,
    .user-name-container,
    .font-header-2,
    [data-testid="user-name"] {
        visibility: hidden !important;
    }

    /* Cache les pseudos dans les pages de jeu */
    .creator-name,
    .text-link,
    .game-card-name,
    .section-content .text-name,
    .player-name,
    [class*="player-name"],
    [class*="user-name"] {
        visibility: hidden !important;
    }

    /* Cache les pseudos sur le chat et les listes d'amis */
    .chat-message .sender-name,
    .friends-content .name,
    .friends-list .text-overflow,
    .friends-online .text-overflow,
    .list-item-name {
        visibility: hidden !important;
    }

    /* Cache les pseudos dans les mini-avatars */
    span[title], a[title] {
        color: transparent !important;
    }

    /* Empêche les hover avec le pseudo */
    [title] {
        pointer-events: none !important;
    }
}
